INSERT OR IGNORE INTO manual_sections
  (manual_key, section_key, title, body, sort_order, version, updated_by, updated_at)
VALUES
  ('owner','spam-protection','Spam protection, cooldowns နှင့် permanent ban','Normal user free-text inquiries ကို spam protection layer က စောင့်ကြည့်ပါတယ်။ Default policy က 10 questions / 10 minutes ဖြစ်ပါတယ်။ 11 ခုမြောက် accepted attempt မှာ AI/FAQ/handoff processing မစခင် cooldown ဝင်ပါတယ်။ ပထမ limit hit = 30 minutes, 24 hours အတွင်း ထပ် hit = 2 hours, တတိယနှင့်နောက်ပိုင်း repeat hit = 12 hours အထိ progressive cooldown ဖြစ်ပါတယ်။ Cooldown/ban ကြောင့် reject လုပ်ထားသော spam text ကို FAQ escalation case အသစ်အဖြစ် မဖန်တီးပါ။ /faq, /language နှင့် အခြား safe commands တွေကတော့ ဆက်အသုံးပြုနိုင်ပါတယ်။\n\n/limits ကို private bot chat သို့မဟုတ် active Staff Inbox group ထဲမှာ သုံးနိုင်ပါတယ်။ User detail မှာ Unlock Now, Exempt 1h, Restrict 2h, Reset Strikes ကို Owner/Sudo သုံးနိုင်ပါတယ်။ Test account ကို rate limit မထိအောင် Exempt 1h သုံးနိုင်ပြီး lock မိပါက Unlock Now နဲ့ ချက်ချင်းပြန်ဖွင့်နိုင်ပါတယ်။\n\nPermanent ban / unban က Owner-only ဖြစ်ပါတယ်။ Permanently Ban ကိုနှိပ်လျှင် confirmation screen ကို အရင်ပြပြီး Yes, Permanently Ban ကို ထပ်အတည်ပြုမှ free-text inquiries ကိုပိတ်ပါတယ်။ Banned account အတွက် AI call နှင့် escalation အသစ် မလုပ်ပါ။ /faq ကဲ့သို့ read-only knowledge access ကို မပိတ်ပါ။ Unban User က ban state ကိုဖယ်ပြီး cooldown/window ကိုလည်း reset လုပ်ပါတယ်။ Admin overrides နှင့် ban/unban actions ကို admin audit log ထဲမှတ်တမ်းတင်ပါတယ်။',90,1,0,CURRENT_TIMESTAMP),
  ('admin','spam-protection','User rate limits နှင့် testing override','Normal user free-text inquiries အတွက် 10 questions / 10 minutes rate window သုံးပါတယ်။ Limit hit ဖြစ်ပါက 30 minutes cooldown စပြီး 24 hours အတွင်း ထပ်မံ hit လျှင် 2 hours, ထပ်မံ hit လျှင် 12 hours အထိ တိုးနိုင်ပါတယ်။ Reject လုပ်ထားသော spam messages ကို case အသစ်မဖန်တီးဘဲ /faq browsing နှင့် safe commands ကို ဆက်ခွင့်ပြုပါတယ်။\n\n/limits ကို bot private chat သို့မဟုတ် active Staff Inbox group မှာဖွင့်ပြီး affected users ကို pager နဲ့ကြည့်နိုင်ပါတယ်။ Unlock Now က cooldown/temporary restriction ကို ချက်ချင်းဖယ်ပေးပါတယ်။ Exempt 1h ကို test account စမ်းသပ်ရာမှာသုံးနိုင်ပါတယ်။ Restrict 2h က manual temporary restriction ဖြစ်ပြီး Reset Strikes က progressive history/window counter ကို reset လုပ်ပါတယ်။\n\nSudo Admin သည် permanent ban/unban မလုပ်နိုင်ပါ။ Permanent ban/unban သည် Bot Owner-only control ဖြစ်ပါတယ်။',90,1,0,CURRENT_TIMESTAMP);
